<script setup lang="ts">defineProps<{ kind: "loading" | "empty" | "error" | "offline" | "paused" | "blocked"; title: string; message: string; action?: string }>(); const emit = defineEmits<{ action: [] }>();</script><template><section class="content-state-panel" :class="`state-${kind}`" role="status" aria-live="polite"><span class="state-symbol" aria-hidden="true">{{ kind === "loading" ? "···" : kind === "error" ? "!" : kind === "offline" ? "⌁" : "○" }}</span><h2>{{ title }}</h2><p>{{ message }}</p><button v-if="action" class="portal-secondary-button" type="button" @click="emit('action')">{{ action }}</button></section></template>
